mapper.select:
SELECT m.id, m.api_key_id AS apiKeyId, k.key_name AS apiKeyName, m.model_name AS modelName, m.model_avatar AS modelAvatar, m.model, m.platform, m.model_type AS modelType, m.temperature, m.max_tokens AS maxTokens, m.max_messages AS maxMessages, m.support_multimodal AS supportMultimodal, m.sort_order AS sortOrder, m.is_default AS isDefault, m.status, m.remark FROM bedrock_ai_model m LEFT JOIN bedrock_ai_api_key k ON m.api_key_id = k.id AND k.is_deleted = 0 WHERE m.is_deleted = 0
AND m.model_name LIKE concat('%', #{param.modelName}, '%')
AND m.model LIKE concat('%', #{param.model}, '%')
AND m.platform = #{param.platform}
AND m.model_type = #{param.modelType}
AND m.status = #{param.status}
ORDER BY m.sort_order ASC, m.create_time DESC
